+
+    expect(selectLatestPublished(posts, 2).map((p) => p.slug)).toEqual([
+      "c",
+      "b",
+    ]);
+  });
+
+  test("parses frontmatter, slug, tags, draft, and reading time", () => {
+    const source = `---
+title: Product judgment
+publishedAt: 2026-06-01
+summary: Why judgment beats slogans.
+tags: product, ai
+draft: true
+---
+
