import { describe, expect, test } from "bun:test";
import {
  estimateReadingTimeMinutes,
  parsePostSource,
  selectLatestPublished,
  selectPublishedPosts,
  tryParsePostSource,
  type PostRecord,
} from "./writings";

function post(partial: Partial<PostRecord> & Pick<PostRecord, "slug">): PostRecord {
