(() => {
  const de = document.documentElement;
  const body = getComputedStyle(document.body);
  const root = getComputedStyle(de);
  const heatScroller = document.querySelector('section:nth-of-type(2) .overflow-x-auto');
  const months = [...document.querySelectorAll('section:nth-of-type(2) [class*="grid"][aria-hidden] span')].filter(s=>s.textContent.trim());
  const lastMonth = months.at(-1);
  const lastCell = document.querySelector('section:nth-of-type(2) [role="img"] > div:last-child > button:last-of-type');
  const header = document.querySelector('header > div');
  const hr = header.getBoundingClientRect();
  return {
    darkClass: de.className,
    overflowX: de.scrollWidth - de.clientWidth,
    bodyBg: body.backgroundColor,
    bodyColor: body.color,
    bodyFont: body.fontFamily.slice(0, 60),
    accent: root.getPropertyValue('--color-accent').trim(),
    header: { center: ((hr.left + hr.right) / 2) / innerWidth, width: hr.width },
    heat: heatScroller ? { scroll: heatScroller.scrollWidth, client: heatScroller.clientWidth, overflow: heatScroller.scrollWidth - heatScroller.clientWidth } : null,
    heatRightEdge: lastCell ? Math.round(lastCell.getBoundingClientRect().right) : null,
    lastMonthLabel: lastMonth ? { text: lastMonth.textContent, x: Math.round(lastMonth.getBoundingClientRect().x) } : null,
    introAvatar: !!document.querySelector('main img[alt*="Portrait"]'),
    footerText: document.querySelector('footer').textContent.replace(/\s+/g,' ').trim().slice(0,120),
  };
})()

